<script setup lang="ts">import { Head, Link, useForm } from '@inertiajs/vue3'; import { Button } from '@/components/ui/button'; import { Input } from '@/components/ui/input'; import { Label } from '@/components/ui/label'; type Period={id:string;label:string;standard_labor_rate_per_kg:number;labor_rate_reason:string|null}; const props=defineProps<{period:Period}>(); const form=useForm({rate:props.period.standard_labor_rate_per_kg,reason:props.period.labor_rate_reason??''});</script><template><Head title="Tarifa de mano de obra" /><main class="flex flex-1 flex-col gap-5 p-4 md:p-6"><header><p class="text-sm text-muted-foreground">Periodo {{ period.label }}</p><h1 class="text-2xl font-semibold">Tarifa estándar de mano de obra</h1><p class="text-sm text-muted-foreground">Valor analítico aplicado por kilogramo de harina.</p></header><form class="grid max-w-xl gap-5 rounded-xl border bg-card p-5" @submit.prevent="form.put(`/cost-periods/${period.id}/labor-rate`)"><div class="grid gap-2"><Label>Tarifa COP por kg</Label><Input v-model.number="form.rate" type="number" min="0" required /></div><div class="grid gap-2"><Label>Motivo o referencia</Label><textarea v-model="form.reason" required rows="3" class="rounded-md border bg-transparent px-3 py-2 text-sm" /></div><div class="flex justify-end gap-2"><Button variant="outline" as-child><Link :href="`/cost-periods/${period.id}`">Cancelar</Link></Button><Button type="submit" :disabled="form.processing">Guardar tarifa</Button></div></form></main></template>
